import zipfile
import io
import pandas as pd
import base64
import os

# Pasta onde os arquivos CSV serão salvos
PASTA_SAIDA = "/home/node/dados_extraidos"
os.makedirs(PASTA_SAIDA, exist_ok=True)

# Localiza e decodifica o arquivo ZIP enviado no webhook
arquivo_base64 = items[0]["binary"].get("data0", {}).get("data")
if not arquivo_base64:
    return {
        "webhookResponse": {
            "erro": "Arquivo binário 'data' não encontrado no payload."
        }
    }

arquivo_binario = base64.b64decode(arquivo_base64)

# Processa o ZIP e extrai os arquivos CSV
try:
    zip_io = io.BytesIO(arquivo_binario)
    with zipfile.ZipFile(zip_io, 'r') as zip_ref:
        resultados = []

        for nome in zip_ref.namelist():
            if nome.endswith(".csv"):
                with zip_ref.open(nome) as f:
                    df = pd.read_csv(f, encoding="utf-8")

                    # Normaliza os nomes das colunas
                    df.columns = [col.strip().lower().replace(" ", "_") for col in df.columns]

                    # Salva o CSV no sistema de arquivos
                    caminho_csv = os.path.join(PASTA_SAIDA, nome)
                    df.to_csv(caminho_csv, index=False)

                    # Verificação de leitura
                    amostra = df.head(3).to_dict(orient="records")

                    resultados.append({
                        "arquivo": nome,
                        "linhas": len(df),
                        "colunas": len(df.columns),
                        "amostra": amostra
                    })

    return {
        "webhookResponse": {
            "mensagem": "Arquivos extraídos com sucesso.",
            "arquivos": resultados
        }
    }

except Exception as e:
    return {
        "webhookResponse": {
            "erro": "Erro ao descompactar o arquivo ZIP.",
            "detalhe": str(e)
        }
    }

