// Supondo que o HTTP Request node se chama “Chamar LLM”
const choices = $json.choices;
if (!choices || !choices.length) {
  throw new Error("Nenhuma resposta da LLM");
}
const content = choices[0].message.content.trim();
// Em caso de vir com aspas ou formatação extra, use .replace ou regex para limpar, se quiser.
return [{ json: { sql: content } }];

const result = $json;
const keys = Object.keys(result);
return {
  json: {
    resposta: result[keys[0]]
  }
};

const contexto = $json.contexto;
const pergunta = $json.body.pergunta;

const full_prompt = `${contexto}\n\nPergunta: ${pergunta}\n\nSQL:`;

return [
  {
    json: {
      full_prompt,
    },
  },
];

const prompt = $input.item.json.full_prompt || "Prompt padrão de teste";

// Crie um objeto de saída especial para inspeção
const debugOutput = {
  original_input: $input.item.json,
  processed_prompt: prompt,
  groq_payload: {
    model: "llama3-70b-8192",
    messages: [{
      role: "user",
      content: prompt
    }],
    temperature: 0.2
  },
  timestamp: new Date().toISOString()
};

// Retorne tanto os dados para a API quanto para inspeção
return {
  json: {
    groq_payload: JSON.stringify(debugOutput.groq_payload),
    INSPECIONAR_ESTE_CAMPO: debugOutput
  }
};

// Extrai o SQL gerado
let sqlOriginal = $json.sql || "";

// Limpeza passo a passo
let sqlLimpa = sqlOriginal.trim()
  // remove crases no início/fim
  .replace(/^`+/, "").replace(/`+$/, "")
  // remove blocos markdown ```sql e ```
  .replace(/^```sql/, "").replace(/```$/, "")
  .trim()
  // junta linhas em uma só, tirando espaços extras de cada linha
  .split("\n").map(l => l.trim()).join(" ").trim();

// Retornar ambas para inspeção
return {
  json: {
    sql_original: sqlOriginal,
    sql_limpa: sqlLimpa
  }
};
